entry_points.template:
/** Foundational utility for {project_name} */
export function formatLabel(name: string): string {
  return name.trim().toLowerCase();
}

smoke_tests.template:
import { describe, it, expect } from 'vitest';
import { formatLabel } from '../../src/lib/utils/format';

describe('formatLabel', () => {
  it('formats lowercase label correctly', () => {
    expect(formatLabel('  MyProject ')).toBe('myproject');
  });
});
